export function lit<T = unknown>(value: T, options: LitOptions = {}): ColumnExpr<T> {
    const expr = seqRange(value, { ...options, mode: "constant" });
    expr._isLiteral = true;
    expr._literalValue = value;
    return expr as ColumnExpr<T>;
}

