ArrayExpr.explode.code:
explode({ emptyAsNull = true, keepNulls = true }: ExplodeOptions = {}) {
    return this._expr._derive((vArray: ColumnData) => {
        const height = vArray.length;
        let newHeight = 0;
        for (let i = 0; i < height; i++) {
            const val = vArray[i];
            if (isArrayOrTypedArray(val)) {
                newHeight += val.length || (emptyAsNull ? 1 : 0);
                continue;
            }

            if (val != null) {
                newHeight += 1;
                continue;
            }

            if (keepNulls) {
                newHeight += 1;
            }
        }

        const res = new Array(newHeight);
        const rowMap = new Int32Array(newHeight);
        let idx = 0;
        for (let i = 0; i < height; i++) {
            const val = vArray[i];
            if (isArrayOrTypedArray(val)) {
                const len = val.length;
                if (len > 0) {
                    for (let j = 0; j < len; j++) {
                        rowMap[idx] = i;
                        res[idx++] = val[j];
                    }
                    continue;
                }
                if (emptyAsNull) {
                    rowMap[idx] = i;
                    res[idx++] = null;
                }
                continue;
            }

            if (val != null) {
                rowMap[idx] = i;
                res[idx++] = val;
                continue;
            }

            if (keepNulls) {
                rowMap[idx] = i;
                res[idx++] = null;
            }
        }
        (res as unknown as { rowMap: Int32Array }).rowMap = rowMap;
        return res;
    });
}

