ArrayExpr.toStruct.code:
toStruct({ upperBound, fields }: ToStructOptions = {}) {
    return this._expr._derive((vArray: ColumnData) => {
        const height = vArray.length;
        const result = new Array(height);

        let width = 0;
        if (Array.isArray(fields)) {
            width = fields.length;
        } else if (typeof upperBound === "number") {
            width = upperBound;
        } else {
            for (let i = 0; i < height; i++) {
                const val = vArray[i];
                if (isArrayOrTypedArray(val) && val.length > width) {
                    width = val.length;
                }
            }
        }

        if (width === 0) {
            throw new ComputeError("toStruct failed: struct width is 0");
        }

        const names = new Array<string>(width);
        for (let j = 0; j < width; j++) {
            if (typeof fields === "function") {
                names[j] = fields(j);
            } else {
                names[j] = (Array.isArray(fields) ? fields[j] : null) ?? `field_${j}`;
            }
        }

        for (let i = 0; i < height; i++) {
            const val = vArray[i];
            if (!isArrayOrTypedArray(val)) {
                result[i] = null;
                continue;
            }
            const obj: Record<string, unknown> = {};
            for (let j = 0; j < width; j++) {
                obj[names[j]] = getArrayElement(val, j, true);
            }
            result[i] = obj;
        }
        return result;
    });
}

