const chainRows = chainedResult.toDicts() as any[];
if (chainRows[0].name !== "C" || chainRows[0].score !== 95 || chainRows[2].name !== "A" || chainRows[2].score !== 50) {
    throw new Error("Post-concat pipeline results mismatch");
}

