DataFrame.dtypes.code:
get dtypes(): RegisteredDataType[] {
    const keys = Object.keys(this._columns);
    const len = keys.length;
    const result = new Array(len);
    for (let i = 0; i < len; i++) {
        result[i] = this._schema[keys[i]];
    }
    return result;
}

