DataFrame.filter.code:
filter(...exprs: FilterPredicateArg<T>[]): DataFrame<T> {
    const height = this._height;
    if (height === 0) return this;

    const flatExprs = exprs.flat(Infinity);
    const keys = Object.keys(this._columns);
    const exprSelectors: IExpr[] = [];
    const funcPredicates: RowPredicateFn<T>[] = [];

    for (let i = 0; i < flatExprs.length; i++) {
        const expr = flatExprs[i];
        if (typeof expr === "function") funcPredicates.push(expr as RowPredicateFn<T>);
        else exprSelectors.push(expr as IExpr);
    }

    const normalizedSelectors = DataFrame._normalizeArgs(exprSelectors);
    const expandedExprs = resolveColumnSelectors(normalizedSelectors, keys, undefined, this._schema, this._columns);
    const numExprs = expandedExprs.length;
    const numFuncs = funcPredicates.length;

    const evaluatedExprs: ColumnData[] = new Array(numExprs);
    for (let i = 0; i < numExprs; i++) {
        evaluatedExprs[i] = expandedExprs[i]._evaluate(this._columns, height);
    }

    let currentIndex = 0;
    let rowObj: T | null = null;
    if (numFuncs > 0) {
        const columns = this._columns;
        rowObj = {} as unknown as T;
        for (let k = 0; k < keys.length; k++) {
            const key = keys[k];
            const col = columns[key];
            Object.defineProperty(rowObj, key, {
                get() {
                    const val = col[currentIndex];
                    return val === undefined ? null : val;
                },
                enumerable: true,
                configurable: true
            });
        }
    }

    const mask = new Array<boolean>(height);
    let matchCount = 0;
    rowLoop: for (let i = 0; i < height; i++) {
        for (let j = 0; j < numExprs; j++) {
            if (!evaluatedExprs[j][i]) {
                mask[i] = false;
                continue rowLoop;
            }
        }
        if (rowObj) {
            currentIndex = i;
            for (let j = 0; j < numFuncs; j++) {
                if (!funcPredicates[j](rowObj)) {
                    mask[i] = false;
                    continue rowLoop;
                }
            }
        }
        mask[i] = true;
        matchCount++;
    }

    const newColumns = {} as DataFrameColumns<T>;
    for (let k = 0; k < keys.length; k++) {
        const key = keys[k];
        (newColumns as ColumnDict)[key] = filterByMask(this._columns[key], mask);
    }
    return DataFrame._createDirect<T>(newColumns, this._schema, matchCount);
}

