const typedCols = Array.from(dfTyped.iterColumns());
if (typedCols.length !== 2 || !(typedCols[0] instanceof Int32Array) || !(typedCols[1] instanceof Float64Array)) {
    throw new Error("3. TypedArray iterColumns mismatch");
}

