DataFrame.select.code:
select<U extends RowRecord = RowRecord>(
    ...args: SelectArg[]
): DataFrame<U> {
    const exprs = DataFrame._normalizeArgs(args);
    const allKeys = Object.keys(this._columns);
    const expandedExprs = resolveColumnSelectors(exprs, allKeys, undefined, this._schema, this._columns);

    const numExprs = expandedExprs.length;
    if (numExprs === 0) {
        return DataFrame._createDirect<U>({}, {}, this._height);
    }

    const newColumns: ColumnDict = {};
    const outSchema: DataFrameSchema = {};

    const evaluatedCols = new Array(numExprs);
    const targetKeys = new Array(numExprs);
    const selectedKeys = new Set<string>();
    let activeRowMap: Int32Array | null = null;

    for (let i = 0; i < numExprs; i++) {
        const expr = expandedExprs[i];
        const targetKey = expr._outputName || expr._colName || ALL_COLUMNS_MARKER;

        if (selectedKeys.has(targetKey)) {
            throw new DataFrameError(`Duplicate column selection: "${targetKey}"`);
        }
        selectedKeys.add(targetKey);

        const col = evaluateExpression(expr, this._columns, this._height);
        evaluatedCols[i] = col;
        targetKeys[i] = targetKey;

        const rowMap = col && (col as { rowMap?: Int32Array }).rowMap;
        if (!rowMap) continue;

        if (!activeRowMap) {
            activeRowMap = rowMap;
            continue;
        }

        const len = rowMap.length;
        if (len !== activeRowMap.length) {
            throw new ShapeError(`Mismatched explode heights for "${targetKey}": ${len} !== ${activeRowMap.length}`);
        }
        for (let j = 0; j < len; j++) {
            if (rowMap[j] !== activeRowMap[j]) {
                throw new ShapeError(`Mismatched explode row map for "${targetKey}"`);
            }
        }
    }

    let targetHeight = activeRowMap ? activeRowMap.length : this._height;

    let shouldCollapse = numExprs > 0;
    for (let i = 0; i < numExprs; i++) {
        const expr = expandedExprs[i];
        const isGlobalAgg = expr._aggFn != null && (!expr._partitionBy || expr._partitionBy.length === 0);
        if (!isGlobalAgg && !expr._isLiteral) {
            shouldCollapse = false;
            break;
        }
    }

    for (let i = 0; i < numExprs; i++) {
        const targetKey = targetKeys[i];
        let col = evaluatedCols[i];
        const hasRowMap = col && (col as { rowMap?: Int32Array }).rowMap;

        const len = isArrayOrTypedArray(col) ? col.length : 0;
        const expectedLen = (activeRowMap && !hasRowMap) ? this._height : targetHeight;
        if (len !== expectedLen) {
            throw new ShapeError(`Column height mismatch: Column "${targetKey}" has length ${len}, expected ${expectedLen}`);
        }

        if (activeRowMap && !hasRowMap) {
            col = gatherColumnByIndices(col, activeRowMap as unknown as (number | null)[]);
        }

        evaluatedCols[i] = col;
    }

    if (shouldCollapse) {
        targetHeight = 1;
    }

    for (let i = 0; i < numExprs; i++) {
        const expr = expandedExprs[i];
        const targetKey = targetKeys[i];
        const col = evaluatedCols[i];

        if (this._isPlainCol(expr) && !activeRowMap && !shouldCollapse) {
            outSchema[targetKey] = this._schema[expr._colName!];
            newColumns[targetKey] = Array.isArray(col) ? col.slice() : (col as { slice(): ColumnData }).slice();
            continue;
        }
        const type = resolveExprOutputType(expr, this._schema, col) || inferColumnType(col);

        outSchema[targetKey] = type;
        newColumns[targetKey] = coerceColumn(col, type, targetHeight);
    }

    return DataFrame._createDirect<U>(newColumns, outSchema, targetHeight);
}

tests.bench:
import { DataFrame } from "df-script";
import { $df } from "df-script";
import { benchCompare } from "../benchHelper";

console.log("=================================================");
console.log("BENCHMARK: DataFrame.select vs Raw V8 Baselines");
console.log("=================================================");

const ROW_COUNT = 100_000;
console.log(`Generating dataset with ${ROW_COUNT.toLocaleString()} rows...`);

const ids: number[] = new Array(ROW_COUNT);
const prices: number[] = new Array(ROW_COUNT);
const quantities: number[] = new Array(ROW_COUNT);
const categories: string[] = new Array(ROW_COUNT);
const CATEGORY_OPTIONS = ["Electronics", "Clothing", "Home", "Books", "Sports"];

for (let i = 0; i < ROW_COUNT; i++) {
    ids[i] = i;
    prices[i] = 10 + (i % 100);
    quantities[i] = 1 + (i % 20);
    categories[i] = CATEGORY_OPTIONS[i % CATEGORY_OPTIONS.length];
}

const df = new DataFrame({
    id: ids,
    price: prices,
    quantity: quantities,
    category: categories
});

// ─── Scenario 1: Direct Column Projection (subset of columns) ─────────────────
benchCompare(
    "Column Projection (3 of 4 columns, 100k rows)",
    // Raw V8 Baseline: shallow reference borrow into new object
    () => {
        return {
            id: ids,
            price: prices,
            category: categories
        };
    },
    // df-script
    () => {
        return df.select("id", "price", "category");
    }
);

// ─── Scenario 2: Binary Arithmetic Expression (price * quantity) ───────────────
benchCompare(
    "Binary Arithmetic (price * quantity, 100k rows)",
    // Raw V8 Baseline: cached length for-loop
    () => {
        const len = prices.length;
        const total = new Float64Array(len);
        for (let i = 0; i < len; i++) {
            total[i] = prices[i] * quantities[i];
        }
        return { total };
    },
    // df-script
    () => {
        return df.select(
            $df.col("price").mul($df.col("quantity")).alias("total")
        );
    }
);

// ─── Scenario 3: Compound Arithmetic ((price * quantity) + 15) ────────────────
benchCompare(
    "Compound Arithmetic ((price * quantity) + 15, 100k rows)",
    // Raw V8 Baseline: single-pass compound arithmetic
    () => {
        const len = prices.length;
        const totalWithTax = new Float64Array(len);
        for (let i = 0; i < len; i++) {
            totalWithTax[i] = prices[i] * quantities[i] + 15;
        }
        return { totalWithTax };
    },
    // df-script
    () => {
        return df.select(
            $df.col("price").mul($df.col("quantity")).add(15).alias("totalWithTax")
        );
    }
);

// ─── Scenario 4: Global Aggregations (sum & mean of 100k rows) ────────────────
benchCompare(
    "Global Aggregations (sum(price), mean(quantity), 100k rows)",
    // Raw V8 Baseline: single-pass accumulator
    () => {
        const len = prices.length;
        let sumPrice = 0;
        let sumQty = 0;
        for (let i = 0; i < len; i++) {
            sumPrice += prices[i];
            sumQty += quantities[i];
        }
        return {
            total_price: [sumPrice],
            avg_qty: [sumQty / len]
        };
    },
    // df-script
    () => {
        return df.select(
            $df.col("price").sum().alias("total_price"),
            $df.col("quantity").mean().alias("avg_qty")
        );
    }
);

