import { $df } from "df-script";

console.log("Running StandardExpr.eq edge-case tests...");

// 1. Basic Primitives Comparison (Numbers, Strings, Booleans, BigInts)
{
    const df = $df.dataFrame({
        nums_a: [10, 20, 30],
        nums_b: [10, 99, 30],
