    { group: "B", val: 4 }
]);
const resOver = dfGrouped.withColumns($df.col("val").lead(1, { fillValue: -1 }).over("group").alias("l")).toDicts() as any[];
if (resOver[0].l !== 2 || resOver[1].l !== -1 || resOver[2].l !== 4 || resOver[3].l !== -1) {
