const emptyDf = $df.dataFrame([] as { val: number }[]);
const resEmpty = emptyDf.select([$df.col("val").lead(1).alias("l")]).toDicts() as any[];
if (resEmpty.length !== 0) throw new Error("lead empty DataFrame failed");

