// -------------------------------------------------------------
const dfAllNullBy = $df.dataFrame([
    { name: "Alice", score: null },
    { name: "Bob", score: null }
]);
const resAllNull = dfAllNullBy.select([
    $df.col("name").maxBy($df.col("score")).alias("top")
]).toDicts() as any[];
if (resAllNull[0].top !== null) {
