    const res = df.select($df.col("val").rand(7, { min: -100, max: -50 }).alias("r")).toDicts() as any[];
    for (const row of res) {
        if (row.r < -100 || row.r > -50) throw new Error(`Test 5 Failed: ${row.r} not in [-100, -50]`);
