        throw new Error(`Test 74 Failed: ${JSON.stringify(res)}`);
    }
}

// Test 75: Extreme edge-case - reducer returning non-primitive array / list (implosion per window)
{
    const df = $df.dataFrame({ v: [1, 2, 3] });
    const res = df.select(
