]).toDicts() as any[];
if (Math.abs(resArray[0].c - (-1)) > 1e-6) {
    throw new Error("Case 3 failed: vector array spearmanCorr");
}

// -------------------------------------------------------------
// Case 4: Tied ranks (fractional rank assignment)
// -------------------------------------------------------------
const dfTies = $df.dataFrame([
    { a: 1, b: 10 },
    { a: 2, b: 20 },
    { a: 2, b: 20 },
    { a: 3, b: 30 }
]);
const resTies = dfTies.select([
