TemporalExpr.offsetDay.code:
offsetDay(n: NumericArg, options: DayOffsetOptions = {}) {
    return this._expr._deriveBinary(n, (v: unknown, nVal: unknown) => {
        const d = toValidDate(v);
        if (!d || nVal == null) return null;
        const daysToAdd = offsetDay(d, nVal as number, options);
        return new Date(d.getTime() + daysToAdd * MS_PER_DAY);
    });
}

TemporalExpr.offsetDay.signatureDetailed:
$df.col(<column_name>).dt.offsetDay(
  n: number | bigint | IExpr | null,
  options: {
    excludeWeekdays?: number[] = [6, 7],
    holidays?: (Date | string | number)[] | Set<number>,
    roll?: "raise" | "forward" | "backward" = "raise"
  } = {}
)

