_alignEmptySideIndices.code:
function _alignEmptySideIndices(
    how: string,
    leftHeight: number,
    rightHeight: number
): { leftIndices: number[]; rightIndices: (number | null)[] } | null {
    if (leftHeight > 0 && rightHeight > 0) return null;

    const keepLeft = (how === "left" || how === "anti" || how === "outer") && leftHeight > 0;
    const keepRight = (how === "right" || how === "outer") && rightHeight > 0;
    if (!keepLeft && !keepRight) return { leftIndices: [], rightIndices: [] };

    const len = keepLeft ? leftHeight : rightHeight;
    const leftIndices: number[] = new Array(len);
    const rightIndices: (number | null)[] = new Array(len);

    for (let i = 0; i < len; i++) {
        leftIndices[i] = keepLeft ? i : UNMATCHED_ROW_INDEX;
        rightIndices[i] = keepLeft ? null : i;
    }
    return { leftIndices, rightIndices };
}

_appendUnmatchedRightRows.code:
function _appendUnmatchedRightRows(
    leftIndices: number[],
    rightIndices: (number | null)[],
    matchedRightIndices: Uint8Array,
    rightHeight: number
): void {
    for (let j = 0; j < rightHeight; j++) {
        if (matchedRightIndices[j] === 1) continue;
        leftIndices.push(UNMATCHED_ROW_INDEX);
        rightIndices.push(j);
    }
}

_applyMixins.code:
function _applyMixins(derivedCtor: { prototype: object }, constructors: Array<{ prototype: object }>) {
    for (const ctor of constructors) {
        const desc = Object.getOwnPropertyDescriptors(ctor.prototype);
        delete (desc as { constructor?: unknown }).constructor;
        Object.defineProperties(derivedCtor.prototype, desc);
    }
}

_blitStackedColumns.code:
function _blitStackedColumns<U extends RowRecord>(
    items: DataFrame<RowRecord>[],
    columns: string[],
    outSchema: DataFrameSchema,
    totalHeight: number,
    allowTyped: boolean = false
): DataFrame<U> {
    const newColumns: Record<string, ArrayLike<unknown>> = {};

    for (let c = 0; c < columns.length; c++) {
        const key = columns[c];
        const type = outSchema[key];
        let allTyped = Boolean(allowTyped && type);
        if (allTyped) {
            for (let i = 0; i < items.length; i++) {
                if (!isTypedArray(items[i]._columns[key])) {
                    allTyped = false;
                    break;
                }
            }
        }
        newColumns[key] = allTyped ? type!.allocate(totalHeight) : new Array(totalHeight).fill(null);
    }

    let offset = 0;
    for (let i = 0; i < items.length; i++) {
        const df = items[i];
        const h = df.height;
        if (h === 0) continue;

        for (let c = 0; c < columns.length; c++) {
            const key = columns[c];
            const src = df._columns[key];
            if (src !== undefined) {
                _copyElements(src, newColumns[key], offset, h);
            }
        }
        offset += h;
    }

    return DataFrame._createDirect<U>(newColumns as ColumnDict, outSchema, totalHeight);
}

