function _checkNativeSlot(
    v: unknown,
    tag: string,
    getterOrMethod: Function | undefined,
    expectedReturn?: unknown
): boolean {
    if (!isObj(v)) return false;

    if (getterOrMethod) {
        try {
            const res = getterOrMethod.call(v);
            return expectedReturn !== undefined ? res === expectedReturn : true;
        } catch {
            return false;
        }
    }

    try {
        if (Object.prototype.hasOwnProperty.call(v, Symbol.toStringTag)) return false;
        return Object.prototype.toString.call(v) === tag;
    } catch {
        return false;
    }
}

_cleanNumericString.code:
function _cleanNumericString(str: string, strict: boolean): string | null {

    if (_NON_BASE10_INJECTION_REGEX.test(str)) return null;

    let clean = str.trim();
    if (clean === "") return null;

    if (clean.startsWith("(") && clean.endsWith(")")) {
        clean = "-" + clean.slice(1, -1).trim();
    }

    const lastChar = clean[clean.length - 1];
    if ((lastChar === "-" || lastChar === "+") && clean.length > 1) {
        clean = lastChar + clean.slice(0, -1).trim();
    }

    if (!strict) {
        clean = clean.replace(_WHITESPACE_UNDERSCORE_REGEX, "");
    }

    const hasDot = clean.includes(".");
    const hasComma = clean.includes(",");

    if (hasDot && hasComma) {
        const lastDot = clean.lastIndexOf(".");
        const lastComma = clean.lastIndexOf(",");
        const isCommaDecimal = lastComma > lastDot;

        const splitChar = isCommaDecimal ? "." : ",";
        const limitIdx = isCommaDecimal ? lastComma : lastDot;

        const parts = clean.slice(0, limitIdx).split(splitChar);
        if (parts.length > 1 && !_validateGroupLengths(parts)) return null;
        if (parts[0].replace(_LEADING_SIGN_REGEX, "").length > 3) return null;

        return isCommaDecimal
            ? clean.replace(_ALL_DOTS_REGEX, "").replace(_ALL_COMMAS_REGEX, ".")
            : clean.replace(_ALL_COMMAS_REGEX, "");
    }

    if (hasComma || hasDot) {
        const char = hasComma ? "," : ".";
        const parts = clean.split(char);

        if (parts.length > 2 || (char === "," && parts.length === 2 && parts[1].length === 3)) {
            const leadLength = parts[0].replace(_LEADING_SIGN_REGEX, "").length;

            if (leadLength === 0) {
                if (char === "," || parts.length > 2) return null;
            } else if (leadLength > 3) {
                return null;
            } else {
                if (!_validateGroupLengths(parts)) return null;
                return clean.replace(hasComma ? _ALL_COMMAS_REGEX : _ALL_DOTS_REGEX, "");
            }
        }
        if (hasComma) {
            return clean.replace(_ALL_COMMAS_REGEX, ".");
        }
    }

    return clean;
}

_collectJsonRecursive.code:
function _collectJsonRecursive(val: unknown, tok: JsonToken, results: unknown[], visited = new Set<object>()): void {
    if (val == null || !isSafeObjPropertyKey(tok.key) || typeof val !== "object" || visited.has(val)) return;

    visited.add(val);

    const isArr = Array.isArray(val);
    if (!isArr && !isObj(val)) return;

    const children = isArr ? val : Object.values(val);

    if (tok.key === _WILDCARD) {
        for (let i = 0; i < children.length; i++) results.push(children[i]);
    } else if (!isArr && Object.hasOwn(val, tok.key)) {
        results.push(val[tok.key]);
    }

    for (let i = 0; i < children.length; i++) {
        _collectJsonRecursive(children[i], tok, results, visited);
    }
}

_collectPatternCandidates.code:
function _collectPatternCandidates<T>(
    input: string,
    pattern: string | RegExp,
    patternIndex: number,
    options: { literal?: boolean; mode?: EscapeRegexOptions["mode"]; asciiCaseInsensitive?: boolean } | undefined,
    createPayload: (match: RegExpExecArray, start: number, end: number) => T
): CandidateMatch<T>[] {
    const { literal = false, mode, asciiCaseInsensitive = false } = options ?? {};
    const escapedPat = literal ? escapeRegExp(pattern, { mode }) : pattern;
    const cleanObj = toCleanRegExp(input, escapedPat, { global: true, asciiCaseInsensitive });
    const reg = cleanObj?.reg ?? null;
    if (!reg) return [];

    const candidates: CandidateMatch<T>[] = [];
    reg.lastIndex = 0;
    let match: RegExpExecArray | null;

    while ((match = reg.exec(input)) !== null) {
        const start = match.index;
        const end = reg.lastIndex;
        const payload = createPayload(match, start, end);

        candidates.push({ _i: patternIndex, _start: start, _end: end, _payload: payload });

        if (start === end) {
            if (start === input.length) break;
            reg.lastIndex = start + _getCodePointStep(input, start);
        }
    }
    return candidates;
}

_computeRanks.code:
function _computeRanks(arr: Float64Array): Float64Array {
    const len = arr.length;
    const indices = new Int32Array(len);
    for (let i = 0; i < len; i++) {
        indices[i] = i;
    }

    indices.sort((a, b) => arr[a] - arr[b]);
    const ranks = new Float64Array(len);
    let i = 0;
    while (i < len) {
        let j = i + 1;
        while (j < len && arr[indices[j]] === arr[indices[i]]) {
            j++;
        }
        const rank = (i + 1 + j) / 2;
        for (let k = i; k < j; k++) {
            ranks[indices[k]] = rank;
        }
        i = j;
    }

    return ranks;
}

_computeWelfordMatrix.code:
function _computeWelfordMatrix(
    xArr: ArrayLike<number>,
    yArr: ArrayLike<number>,
    count: number
): { covariance: number | null; correlation: number | null } | null {
    if (count < 2) return null;

    let meanX = 0, meanY = 0;
    let M2_X = 0, M2_Y = 0;
    let C_XY = 0;

    for (let i = 0; i < count; i++) {
        const x = xArr[i];
        const y = yArr[i];

        const deltaX = x - meanX;
        meanX += deltaX / (i + 1);
        const deltaX2 = x - meanX;

        const deltaY = y - meanY;
        meanY += deltaY / (i + 1);
        const deltaY2 = y - meanY;

        C_XY += deltaX * deltaY2;
        M2_X += deltaX * deltaX2;
        M2_Y += deltaY * deltaY2;
    }

    const covariance = C_XY / (count - 1);

    if (M2_X === 0 || M2_Y === 0) {
        return { covariance, correlation: null };
    }

    const denominator = Math.sqrt(M2_X * M2_Y);
    if (denominator === 0 || Number.isNaN(denominator)) {
        return { covariance, correlation: null };
    }

    const correlation = clamp(C_XY / denominator, { min: -1, max: 1 });
    return { covariance, correlation };
}

_copyElements.code:
function _copyElements(src: ArrayLike<unknown>, dest: ArrayLike<unknown> | unknown[], offset: number, count: number): void {
    if (isTypedArray(src) && isTypedArray(dest)) {
        (dest as Uint8Array).set(src as ArrayLike<number>, offset);
        return;
    }
    const destArr = dest as unknown[];
    for (let i = 0; i < count; i++) {
        destArr[offset + i] = src[i];
    }
}

