_expandReplacementString.code:
function _expandReplacementString(
    template: string,
    match: string,
    offset: number,
    fullStr: string,
    captures: (string | undefined)[],
    groups?: Record<string, string>
): string {
    if (!template.includes("$")) return template;
    return template.replace(/\$\$|\$([$'`&]|\d{1,2}|<[^>]+>)/g, (m, token?: string) => {
        if (m === "$$" || token === "$") return "$";
        if (!token) return m;
        if (token === "&") return match;
        if (token === "`") return fullStr.slice(0, offset);
        if (token === "'") return fullStr.slice(offset + match.length);
        if (token.startsWith("<")) return groups ? (groups[token.slice(1, -1)] ?? "") : m;

        const idx = Number(token);
        if (idx > 0 && idx <= captures.length) return captures[idx - 1] ?? "";

        if (token.length === 2) {
            const first = Number(token[0]);
            if (first > 0 && first <= captures.length) return (captures[first - 1] ?? "") + token[1];
        }
        return m;
    });
}

_filterNonOverlapping.code:
function _filterNonOverlapping<T>(candidates: CandidateMatch<T>[], leftmost: boolean): CandidateMatch<T>[] {
    const len = candidates.length;
    if (len <= 1) return candidates;

    candidates.sort(leftmost
        ? (a, b) => a._start !== b._start ? a._start - b._start : a._i - b._i
        : (a, b) => a._i - b._i
    );

    const selected: CandidateMatch<T>[] = [];
    if (leftmost) {
        let lastPos = 0;
        for (let i = 0; i < len; i++) {
            const c = candidates[i];
            if (c._start >= lastPos) {
                selected.push(c);
                lastPos = c._end;
            }
        }
        return selected;
    }

    for (let i = 0; i < len; i++) {
        const c = candidates[i];
        let overlaps = false;
        const selLen = selected.length;
        for (let j = 0; j < selLen; j++) {
            const a = selected[j];
            if (_intervalsOverlap(c._start, c._end, a._start, a._end)) {
                overlaps = true;
                break;
            }
        }
        if (!overlaps) selected.push(c);
    }
    return selected;
}

_formatCsvValue.code:
function _formatCsvValue(options: FormatCSVValueOptions = {}) {
    const {
        nullValue = "",
        numericFormatOptions,
        datetimeFormat,
        dateFormat,
        timeFormat,
        replacerOptions
    } = options;
    const formatNum = formatNumber(numericFormatOptions);
    const format = datetimeFormat ?? dateFormat ?? timeFormat;
    const formatDate = (v: Date): string => isValidDateObj(v) ? (format ? strftime(v, { format }) : v.toISOString()) : nullValue;

    const replacer = createSafeJsonReplacer({
        formatDate,
        onBigInt: formatNum,
        ...replacerOptions
    });

    const onBigInt = replacerOptions?.onBigInt;

    return (val: unknown): { str: string; isNumeric: boolean } => {
        if (val == null || typeof val === "symbol" || typeof val === "function" || (val instanceof Date && !isValidDateObj(val))) {
            return { str: nullValue, isNumeric: false };
        }

        const raw = unboxPrimitiveObj(val);
        const t = typeof raw;
        if (t === "number") {
            return { str: formatNum(raw), isNumeric: true };
        }
        if (t === "bigint") {
            const custom = onBigInt ? onBigInt(raw as bigint) : formatNum(raw);
            return { str: String(custom), isNumeric: true };
        }
        if (t === "boolean" || t === "string") {
            return { str: String(raw), isNumeric: false };
        }

        const res = unboxPrimitiveObj(replacer.call(null, "", val));
        if (res == null || typeof res === "symbol" || typeof res === "function") {
            return { str: nullValue, isNumeric: false };
        }
        return {
            str: typeof res === "object" ? JSON.stringify(res, replacer) : String(res),
            isNumeric: false
        };
    };
}

_getCachedDtf.code:
function _getCachedDtf(timeZone: string): Intl.DateTimeFormat {
    let dtf = _dtfCache.get(timeZone);
    if (!dtf) {
        dtf = new Intl.DateTimeFormat("en-US", {
            timeZone,
            hourCycle: "h23",
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            second: "2-digit",
            fractionalSecondDigits: 3
        });
        _dtfCache.set(timeZone, dtf);
    }
    return dtf;
}

