_getDateTimeParts.code:
function _getDateTimeParts(d: Date, timeZone?: string): DateTimeParts {
    const tz = _resolveTimeZone(timeZone);

    if (tz.toUpperCase() === "UTC") {
        return {
            year: d.getUTCFullYear(),
            month: d.getUTCMonth() + 1,
            day: d.getUTCDate(),
            hour: d.getUTCHours(),
            minute: d.getUTCMinutes(),
            second: d.getUTCSeconds(),
            ms: d.getUTCMilliseconds(),
            dayOfWeek: d.getUTCDay(),
            timeZone: "UTC"
        };
    }

    const dtf = _getCachedDtf(tz);
    const parts = dtf.formatToParts(d);

    const values: Record<string, string> = {
        year: "0",
        month: "0",
        day: "0",
        hour: "0",
        minute: "0",
        second: "0",
        fractionalSecond: "0"
    };

    for (let i = 0, len = parts.length; i < len; i++) {
        const part = parts[i];
        if (part.type in values) {
            values[part.type] = part.value;
        }
    }

    const year = parseInt(values.year, 10);
    const month = parseInt(values.month, 10);
    const day = parseInt(values.day, 10);
    let hour = parseInt(values.hour, 10);
    if (hour === 24) hour = 0;

    const ms = Math.round(parseFloat("0." + values.fractionalSecond) * 1000) || 0;
    const dayOfWeek = createUTCDate(year, month - 1, day).getUTCDay();

    return {
        year,
        month,
        day,
        hour,
        minute: parseInt(values.minute, 10),
        second: parseInt(values.second, 10),
        ms,
        dayOfWeek,
        timeZone: tz
    };
}

_getDecimalMaxVal.code:
function _getDecimalMaxVal(precision: number, scale: number): number | null {
    const integerDigits = precision - scale;
    if (integerDigits < 0 || scale < 0) return null;
    if (integerDigits > 15) {
        return Number.MAX_SAFE_INTEGER;
    }

    const safeScale = clamp(scale, { min: 0, max: 16 });
    const maxVal = Math.pow(10, integerDigits) - Math.pow(10, -safeScale);
    return maxVal > 0 ? maxVal : null;
}

_getISO.code:
function _getISO(y: number, m: number, d: number, field: "week" | "year" = "week"): number | null {
    const date = createUTCDate(y, m - 1, d);
    date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
    if (field === "year") return date.getUTCFullYear();
    const ordinal = _getOrdinalDay(date);
    return ordinal != null ? Math.floor((ordinal - 1) / 7) + 1 : null;
}

_getOrdinalDay.code:
function _getOrdinalDay(d: Date): number | null {
    if (!isValidDateObj(d)) return null;
    const start = createUTCDate(d.getUTCFullYear(), 0, 1).getTime();
    return Math.floor((d.getTime() - start) / MS_PER_DAY) + 1;
}

_getSortedValidNumbers.code:
function _getSortedValidNumbers(values: ArrayLike<unknown>): Float64Array | null {
    const len = values.length;
    let validCount = 0;
    const nums = new Float64Array(len);
    for (let i = 0; i < len; i++) {
        const val = values[i];
        const n = toValidNumber(val, { allowNonFiniteNumbers: true });
        if (n !== null && isValidNumber(n, { allowNonFiniteNumbers: true, allowNaN: false })) {
            nums[validCount++] = n;
        }
    }
    if (validCount === 0) return null;
    const validNums = nums.subarray(0, validCount);
    validNums.sort();
    return validNums;
}

_getTargetKeys.code:
function _getTargetKeys(
    expr: unknown,
    allKeys: string[],
    excludeSet: Set<string>,
    schema?: DataFrameSchema
): string[] | null {
    const multiExpr = expr as ColumnExprInternal | undefined;
    if (multiExpr?._colNames?.length && !multiExpr._patterns?.length) {
        return multiExpr._colNames;
    }

    const isExpr = expr instanceof ColumnExpr;
    const isAll = isExpr && expr._colName === ALL_COLUMNS_MARKER;
    const patterns = isExpr && expr._patterns ? expr._patterns : [];
    const exactNames = isExpr && expr._colNames ? expr._colNames : [];
    const types = isExpr && expr._targetTypes ? expr._targetTypes : [];
    const numPatterns = patterns.length;
    const numTypes = types.length;

    if (!isAll && numPatterns === 0 && numTypes === 0) {
        if (isExpr || !isObj(expr) || !("_evaluate" in expr) || expr._colName) {
            return null;
        }
    }

    if (numTypes > 0 && !schema) {
        throw new SchemaError("Cannot resolve DataType without DataFrame schema.");
    }

    const excluded = isAll && expr._excludedCols ? new Set(expr._excludedCols) : null;
    const targets: string[] = [];
    const allLen = allKeys.length;

    for (let i = 0; i < allLen; i++) {
        const key = allKeys[i];
        if (excludeSet.has(key)) continue;

        if (isAll) {
            if (!excluded || !excluded.has(key)) targets.push(key);
            continue;
        }

        if (exactNames.indexOf(key) !== -1) {
            targets.push(key);
            continue;
        }

        let matched = false;
        for (let p = 0; p < numPatterns; p++) {
            patterns[p].lastIndex = 0;
            if (patterns[p].test(key)) {
                matched = true;
                break;
            }
        }

        if (!matched && numTypes > 0 && schema![key]) {
            const colType = schema![key];
            for (let t = 0; t < numTypes; t++) {
                if (colType.matches(types[t])) {
                    matched = true;
                    break;
                }
            }
        }

        if (matched || (!numPatterns && !numTypes)) {
            targets.push(key);
        }
    }

    return targets;
}

_getTimeZoneOffsetMinutes.code:
function _getTimeZoneOffsetMinutes(d: Date, resolvedTz: string): number {
    if (resolvedTz.toUpperCase() === "UTC") return 0;
    const target = _getDateTimeParts(d, resolvedTz);
    const targetMs = createUTCDate(target.year, target.month - 1, target.day, target.hour, target.minute, target.second, target.ms).getTime();
    return Math.round((targetMs - d.getTime()) / MS_PER_MINUTE);
}

_getTypeValidators.code:
function _getTypeValidators(type: ArrayItemType): {
    check: (v: unknown) => boolean;
    coerce: (v: unknown) => unknown;
    isTypedArrayTarget?: boolean;
} {
    if (typeof type === "function") {
        if (isTypedArrayConstructor(type)) {
            const isBigIntTypedArray = type === BigInt64Array || type === BigUint64Array;
            return {
                check: isBigIntTypedArray ? isValidBigInt : isValidNumber,
                coerce: isBigIntTypedArray ? (v) => toValidBigInt(v) : (v) => toValidNumber(v) ?? NaN,
                isTypedArrayTarget: true,
            };
        }
        if (isClass(type)) {
            return { check: (v) => v instanceof type, coerce: (v) => v instanceof type ? v : null };
        }
        return {
            check: (v) => Boolean((type as Function)(v)),
            coerce: (v) => {
                const res = (type as Function)(v);
                return typeof res === "boolean" ? (res ? v : null) : res;
            }
        };
    }

    switch (type) {
        case "string":
            return { check: (v) => typeof v === "string", coerce: (v) => String(v) };
        case "number":
            return { check: isValidNumber, coerce: (v) => toValidNumber(v) ?? NaN };
        case "int":
            return { check: isValidInt, coerce: (v) => toValidInt(v) };
        case "boolean":
            return { check: (v) => typeof v === "boolean", coerce: Boolean };
        case "bigint":
            return { check: isValidBigInt, coerce: (v) => toValidBigInt(v) };
        case "date":
            return { check: isValidDateObj, coerce: (v) => toValidDate(v) };
        case "regexp":
            return {
                check: isRegExp,
                coerce: (v) => isRegExp(v) ? v : (typeof v === "string" ? toCleanRegExp("", v)?.reg ?? null : null)
            };
        case "array":
            return { check: isArrayOrTypedArray, coerce: (v) => isArrayOrTypedArray(v) ? toValidArray(v, { clone: false }) : null };
        case "object":
            return { check: isObj, coerce: (v) => (isObj(v) ? v : null) };
        case "plainObject":
            return { check: isPlainObj, coerce: (v) => (isPlainObj(v) ? v : null) };
        case "null":
            return { check: (v) => v === null, coerce: () => null };
        case "undefined":
            return { check: (v) => v === undefined, coerce: () => undefined };
        case "nullish":
            return { check: (v) => v == null, coerce: () => null };
        case "any":
        default:
            return { check: () => true, coerce: (v) => v };
    }
}

