_intervalsOverlap.code:
function _intervalsOverlap(s1: number, e1: number, s2: number, e2: number): boolean {
    return s1 === e1 || s2 === e2 ? s1 <= e2 && s2 <= e1 : s1 < e2 && s2 < e1;
}

_isDateExcluded.code:
function _isDateExcluded(d: Date, excludeWeekdays: number[], holidayTimestamps: Set<number>): boolean {
    return (excludeWeekdays.length > 0 && excludeWeekdays.includes(d.getUTCDay())) || holidayTimestamps.has(d.getTime());
}

_isUInt8.code:
function _isUInt8(n: unknown): n is number {
    return isValidInt(n, UINT8_INT_OPTS);
}

_isUnicodeSurrogate.code:
function _isUnicodeSurrogate(code: number, options: IsUnicodeSurrogateOptions = {}): boolean {
    if (!isValidInt(code, { range: "UInt16" })) return false;

    const { type = "all" } = options;
    switch (type) {
        case "high": return code >= SURROGATE_HIGH_MIN_CODE && code <= SURROGATE_HIGH_MAX_CODE;
        case "low": return code >= SURROGATE_LOW_MIN_CODE && code <= SURROGATE_LOW_MAX_CODE;
        case "all": return code >= SURROGATE_HIGH_MIN_CODE && code <= SURROGATE_LOW_MAX_CODE;
        default: return false;
    }
}

_isValidTimeZone.code:
function _isValidTimeZone(tz: string): boolean {
    let valid = _tzValidityCache.get(tz);
    if (valid === undefined) {
        try {
            Intl.DateTimeFormat(undefined, { timeZone: tz });
            valid = true;
        } catch {
            valid = false;
        }
        _tzValidityCache.set(tz, valid);
    }
    return valid;
}

_isWrappedJsonComposite.code:
function _isWrappedJsonComposite(str: string, options: { trim?: boolean } = {}): boolean {
    const s = options?.trim ? (stripChars(str) ?? "") : str;
    const len = s.length;
    if (len < 2) return false;
    const fChar = s[0];
    const lChar = s[len - 1];
    return (fChar === "{" && lChar === "}") || (fChar === "[" && lChar === "]");
}

_matchManyCore.code:
function _matchManyCore<T>(
    str: string | null | undefined,
    patterns: (string | RegExp)[] | (string | RegExp),
    options: ExtractManyOptions | undefined,
    resolveSingle: (pat: string | RegExp) => T | null,
    resolvePayload: (res: Record<string, string | null>, start: number) => T
): (T | null)[] | null {
    const { overlapping = false, leftmost, ...engineOpts } = options ?? {};
    const isLeftmost = leftmost ?? true;

    if (overlapping && leftmost) {
        throw new InvalidArgumentError("Cannot specify both 'overlapping' and 'leftmost'");
    }
    if (str == null || patterns == null) return null;
    const list = toValidArray(patterns);
    const len = list.length;
    if (len === 0) return [];

    if (overlapping) {
        const result = new Array<T | null>(len);
        for (let i = 0; i < len; i++) {
            result[i] = resolveSingle(list[i]);
        }
        return result;
    }

    const candidates: CandidateMatch<T>[] = [];

    for (let i = 0; i < len; i++) {
        const cleaned = toCleanRegExp(str, list[i], { ...engineOpts, global: false });
        if (!cleaned) continue;
        const match = cleaned.input.match(cleaned.reg);
        if (match && match.index !== undefined) {
            const start = match.index;
            const matchLen = match[0].length;
            candidates.push({
                _i: i,
                _start: start,
                _end: start + matchLen,
                _payload: resolvePayload(_matchToRecord(match), start)
            });
        }
    }

    const result = new Array<T | null>(len).fill(null);
    if (candidates.length === 0) return result;

    const selected = _filterNonOverlapping(candidates, isLeftmost);

    for (let i = 0; i < selected.length; i++) {
        const c = selected[i];
        result[c._i] = c._payload;
    }

    return result;
}

_matchToRecord.code:
function _matchToRecord(match: RegExpMatchArray | RegExpExecArray): Record<string, string | null> {
    const result: Record<string, string | null> = Object.create(null);
    if (match.index !== undefined) {
        Object.defineProperty(result, "_index", { value: String(match.index), writable: true, configurable: true });
    }
    Object.defineProperty(result, "_length", { value: match.length, writable: true, configurable: true });
    for (let i = 0; i < match.length; i++) {
        result[String(i)] = match[i] !== undefined ? match[i] : null;
    }
    if (match.groups) {
        for (const key in match.groups) {
            const val = match.groups[key];
            result[key] = val !== undefined ? val : null;
        }
    }
    return result;
}

_normalizeEpochToMs.code:
function _normalizeEpochToMs(n: number | bigint): number {
    if (typeof n === "bigint") {
        const abs = n < 0n ? -n : n;
        if (abs <= 30_000_000_000n) return Number(n) * MS_PER_SECOND;
        if (abs <= 100_000_000_000_000n) return Number(n);
        if (abs <= 100_000_000_000_000_000n) return Number(n / US_PER_MS_BI);
        return Number(n / NS_PER_MS_BI);
    }

    const abs = Math.abs(n);
    if (abs <= 3e10) return n * MS_PER_SECOND;
    if (abs <= 1e14) return n;
    if (abs <= 1e17) return Math.floor(n / US_PER_MS);
    return Math.floor(n / NS_PER_MS);
}

_parseBool.code:
function _parseBool(v: string): boolean | null {
    const l = v.toLowerCase();
    return (l === "true" || l === "1") ? true : (l === "false" || l === "0") ? false : null;
}

_parseOffsetMinutes.code:
function _parseOffsetMinutes(offsetStr: string): number {
    const clean = offsetStr.replace(":", "");
    const sign = clean[0] === "+" ? 1 : -1;
    const hours = parseInt(clean.slice(1, 3), 10) || 0;
    const mins = parseInt(clean.slice(3, 5), 10) || 0;
    return sign * (hours * 60 + mins);
}

_replaceRegexChar.code:
function _replaceRegexChar(ch: string): string {
    const code = ch.codePointAt(0)!;
    const isControl = code <= MAX_C0_CONTROL_CODE || code === ASCII_DEL_CODE;
    const isSurrogateChar = ch.length === 1 && _isUnicodeSurrogate(code);

    if (isControl || isSurrogateChar) {
        const named = NAMED_CONTROL_ESCAPES[code];
        if (named) return named;
        const hex = code.toString(16);
        return isControl ? `\\x${hex.padStart(2, "0")}` : `\\u${hex.padStart(4, "0")}`;
    }
    return "\\" + ch;
}

_resolveGroupRecord.code:
function _resolveGroupRecord(
    record: Record<string, string | null>,
    groupIndex: number | string
): string | null {
    if (typeof groupIndex === "string") return record[groupIndex] ?? null;

    const num = Number(groupIndex);
    if (Number.isNaN(num)) return null;

    const index = Math.trunc(num);
    if (index >= 0) return record[String(index)] ?? null;

    let count = 0;
    while (String(count) in record) count++;
    const targetIndex = count + index;
    return targetIndex >= 1 ? (record[String(targetIndex)] ?? null) : null;
}

_resolveHolidaySet.code:
function _resolveHolidaySet(
    holidays?: Set<number> | unknown[],
    excludeWeekdays: number[] = []
): Set<number> {
    const holidayTimestamps = new Set<number>();
    if (!holidays) return holidayTimestamps;

    const hasExcluded = excludeWeekdays.length > 0;
    for (const item of holidays) {
        const hd = toValidDate(item, { dateOnly: true });
        if (!hd || (hasExcluded && excludeWeekdays.includes(hd.getUTCDay()))) continue;
        holidayTimestamps.add(hd.getTime());
    }
    return holidayTimestamps;
}

_resolveJsonPathStep.code:
function _resolveJsonPathStep(item: unknown, tok: JsonToken, next: unknown[]): void {
    if (item == null) return;

    switch (tok.type) {
        case "prop":
            if (isObj(item) && isSafeObjPropertyKey(tok.key) && Object.hasOwn(item, tok.key!)) {
                next.push(item[tok.key!]);
            }
            break;
        case "idx": {
            if (!Array.isArray(item)) break;
            const i = tok.idx! < 0 ? item.length + tok.idx! : tok.idx!;
            if (i >= 0 && i < item.length) next.push(item[i]);
            break;
        }
        case "slice": {
            if (!Array.isArray(item) || tok.step === 0) break;
            const step = tok.step ?? 1;
            const sliced = stepSliceArray(item, {
                step,
                offsetStart: tok.start ?? (step > 0 ? 0 : item.length - 1),
                offsetEnd: tok.end,
                nullOnOob: true
            });
            if (sliced) {
                for (let i = 0; i < sliced.length; i++) next.push(sliced[i]);
            }
            break;
        }
        case "wildcard": {
            const vals = Array.isArray(item) ? item : (isObj(item) ? Object.values(item) : null);
            if (vals) {
                for (let i = 0; i < vals.length; i++) next.push(vals[i]);
            }
            break;
        }
        case "rec":
            _collectJsonRecursive(item, tok, next);
            break;
    }
}

_resolveOffset.code:
function _resolveOffset(val: number | undefined, fallback: number, capacity: number, isOneIndexed = false): number {
    const raw = val ?? fallback;
    return raw < 0 ? capacity + (isOneIndexed ? 1 : 0) + raw : raw;
}

_resolveOperandType.code:
function _resolveOperandType(
    operand: unknown,
    schema: DataFrameSchema
): RegisteredDataType | undefined {
    if (operand == null) return undefined;
    if (operand instanceof DataType) return operand as RegisteredDataType;
    if (isExpr(operand)) return resolveExprOutputType(operand, schema);

    const unboxed = unboxPrimitiveObj(operand);

    // 1. Primitives & Scalars
    if (typeof unboxed === "string") return schema[unboxed] ?? DataTypeRegistry.Utf8;
    if (typeof unboxed === "boolean") return DataTypeRegistry.Boolean;
    if (typeof unboxed === "bigint") {
        return isValidBigInt(unboxed, { range: "Int64" }) ? DataTypeRegistry.Int64 : DataTypeRegistry.UInt64;
    }
    if (isValidNumber(unboxed)) {
        if (isValidInt(unboxed, { range: "Int32" })) return DataTypeRegistry.Int32;
        return Number.isInteger(unboxed) ? DataTypeRegistry.Int64 : DataTypeRegistry.Float64;
    }
    if (isValidDateObj(unboxed)) return DataTypeRegistry.Datetime;
    if (isValidBinary(unboxed, { strict: true })) return DataTypeRegistry.Binary;

    // 2. Collections & Structures
    if (Array.isArray(unboxed)) {
        let innerType: RegisteredDataType | undefined;
        for (let i = 0, len = unboxed.length; i < len; i++) {
            const item = unboxed[i];
            if (item != null && (innerType = _resolveOperandType(item, schema))) break;
        }
        return DataTypeRegistry.Array(innerType ?? DataTypeRegistry.Utf8);
    }

    if (isTypedArray(unboxed)) {
        const tag = typedArrayTagGetter ? typedArrayTagGetter.call(unboxed) : (unboxed as { constructor: { name: string } }).constructor.name;
        const inner = _TYPED_ARRAY_MAP[tag];
        return inner ? DataTypeRegistry.Array(inner) : DataTypeRegistry.Binary;
    }

    if (isObj(unboxed)) return DataTypeRegistry.Object;

    return undefined;
}

