function _trimByMode(str: string, mode: StripMode = "both"): string {
    if (mode === "start") return str.trimStart();
    if (mode === "end") return str.trimEnd();
    return str.trim();
}

_unescapeQuotes.code:
function _unescapeQuotes(str: string): string {
    return str.replace(/\\(.)/g, (_, c) => CONTROL_UNESCAPE_MAP[c] ?? c);
}

_unzipValidNumericPairs.code:
function _unzipValidNumericPairs(pairs: ColumnData<[unknown, unknown]>): { xArr: Float64Array; yArr: Float64Array; count: number } {
    const len = pairs.length;
    const xArr = new Float64Array(len);
    const yArr = new Float64Array(len);
    let count = 0;

    for (let i = 0; i < len; i++) {
        const pair = pairs[i];
        if (!pair) continue;

        const x = toValidNumber(pair[0]);
        const y = toValidNumber(pair[1]);
        if (x === null || y === null) continue;

        xArr[count] = x;
        yArr[count] = y;
        count++;
    }

    return { xArr, yArr, count };
}

