alignAsofIndices.code:
export function alignAsofIndices(
    leftCols: ColumnDict,
    rightCols: ColumnDict,
    leftHeight: number,
    rightHeight: number,
    leftOnKey: string,
    rightOnKey: string,
    leftByKeys: string[],
    rightByKeys: string[],
    options: JoinAsofOptions = {} as JoinAsofOptions
): { leftIndices: number[]; rightIndices: (number | null)[] } {
    const emptyFastPath = _alignEmptySideIndices("left", leftHeight, rightHeight);
    if (emptyFastPath) return emptyFastPath;

    assertColumnExists(leftOnKey, leftCols, "Join on key", " in the left DataFrame.");
    assertColumnExists(rightOnKey, rightCols, "Join on key", " in the right DataFrame.");

    const strategy = options.strategy ?? "backward";
    const allowExactMatches = options.allowExactMatches ?? true;
    const checkSorted = options.checkSorted ?? true;

    const leftNumCol = toArrayOfType(leftCols[leftOnKey], Float64Array, {
        coerce: (v) => toValidNumber(v) ?? NaN
    }) as unknown as Float64Array;
    const rightNumCol = toArrayOfType(rightCols[rightOnKey], Float64Array, {
        coerce: (v) => toValidNumber(v) ?? NaN
    }) as unknown as Float64Array;

    if (checkSorted) {
        const assertSorted = (col: Float64Array, height: number, colName: string, side: string) => {
            for (let i = 1; i < height; i++) {
                const prev = col[i - 1];
                const curr = col[i];
                if (isValidNumber(prev) && isValidNumber(curr) && curr < prev) {
                    throw new InvalidArgumentError(`${side} DataFrame key column "${colName}" is not sorted in ascending order at row ${i}.`);
                }
            }
        };
        assertSorted(leftNumCol, leftHeight, leftOnKey, "left");
        assertSorted(rightNumCol, rightHeight, rightOnKey, "right");
    }

    const hasBy = leftByKeys.length > 0;
    const rightByMap = hasBy ? buildGroupMap(rightCols, rightByKeys, rightHeight) : null;

    const allRightCandidates: number[] = new Array(rightHeight);
    if (!hasBy) {
        for (let c = 0; c < rightHeight; c++) allRightCandidates[c] = c;
    }

    const leftIndices: number[] = new Array(leftHeight);
    const rightIndices: (number | null)[] = new Array(leftHeight);

    const getVal = (_: number, c: number) => rightNumCol[c];

    const matchCandidate = (leftVal: number, candidates: number[]): number | null => {
        const len = candidates.length;
        if (len === 0) return null;

        if (strategy === "backward") {
            const pos = binarySearch(candidates, leftVal, { side: allowExactMatches ? "right" : "left", getValue: getVal }) - 1;
            return pos >= 0 ? candidates[pos] : null;
        }
        if (strategy === "forward") {
            const pos = binarySearch(candidates, leftVal, { side: allowExactMatches ? "left" : "right", getValue: getVal });
            return pos < len ? candidates[pos] : null;
        }

        const pos = binarySearch(candidates, leftVal, { side: "right", getValue: getVal });
        let bIdx = pos - 1, fIdx = pos;
        if (!allowExactMatches) {
            if (bIdx >= 0 && rightNumCol[candidates[bIdx]] === leftVal) bIdx--;
            if (fIdx < len && rightNumCol[candidates[fIdx]] === leftVal) fIdx++;
        }
        if (bIdx < 0) return fIdx < len ? candidates[fIdx] : null;
        if (fIdx >= len) return bIdx >= 0 ? candidates[bIdx] : null;
        const bVal = rightNumCol[candidates[bIdx]];
        const fVal = rightNumCol[candidates[fIdx]];
        return Math.abs(leftVal - bVal) <= Math.abs(leftVal - fVal) ? candidates[bIdx] : candidates[fIdx];
    };

    const tol = options.tolerance !== undefined ? toValidNumber(options.tolerance) : null;

    for (let i = 0; i < leftHeight; i++) {
        leftIndices[i] = i;
        const leftVal = leftNumCol[i];

        if (!isValidNumber(leftVal)) {
            rightIndices[i] = null;
            continue;
        }

        const candidates = hasBy
            ? (rightByMap!.get(computeRowHash(leftCols, leftByKeys, i)) || [])
            : allRightCandidates;

        if (candidates.length === 0) {
            rightIndices[i] = null;
            continue;
        }

        let matchedRIdx = matchCandidate(leftVal, candidates);

        if (matchedRIdx !== null && tol !== null) {
            const rVal = rightNumCol[matchedRIdx];
            if (!isValidNumber(tol) || !isValidNumber(rVal) || Math.abs(leftVal - rVal) > tol) {
                matchedRIdx = null;
            }
        }

        rightIndices[i] = matchedRIdx;
    }

    return { leftIndices, rightIndices };
}

alignKeyIndices.code:
export function alignKeyIndices(
    leftCols: ColumnDict,
    rightCols: ColumnDict,
    leftHeight: number,
    rightHeight: number,
    leftKeys: string[],
    rightKeys: string[],
    options: Partial<JoinOptions> = {}
): { leftIndices: number[]; rightIndices: (number | null)[] } {
    const { how = "inner", joinNulls = false, maintainOrder } = options;

    if (how === "cross") {
        return computeCartesianProduct(leftHeight, rightHeight);
    }

    const emptyFastPath = _alignEmptySideIndices(how, leftHeight, rightHeight);
    if (emptyFastPath) return emptyFastPath;

    const numLeftKeys = leftKeys.length;
    const numRightKeys = rightKeys.length;

    const getRowHashAt = (cols: ColumnDict, keys: string[], numKeys: number, idx: number): string | null => {
        if (!joinNulls) {
            for (let i = 0; i < numKeys; i++) {
                if (cols[keys[i]][idx] == null) return null;
            }
        }
        return computeRowHash(cols, keys, idx);
    };

    // 3. Build hash table for right DataFrame
    const rightHash = new Map<string, number[]>();
    for (let i = 0; i < rightHeight; i++) {
        const hash = getRowHashAt(rightCols, rightKeys, numRightKeys, i);
        if (hash === null) continue;
        let list = rightHash.get(hash);
        if (list === undefined) {
            list = [];
            rightHash.set(hash, list);
        }
        list.push(i);
    }

    const leftIndices: number[] = [];
    const rightIndices: (number | null)[] = [];

    // 4. Semi & Anti joins: left row indices only
    if (how === "semi" || how === "anti") {
        const isSemi = how === "semi";
        for (let i = 0; i < leftHeight; i++) {
            const hash = getRowHashAt(leftCols, leftKeys, numLeftKeys, i);
            const matches = hash === null ? undefined : rightHash.get(hash);
            const hasMatch = matches !== undefined && matches.length > 0;

            if (isSemi === hasMatch) {
                leftIndices.push(i);
                rightIndices.push(null);
            }
        }
        return { leftIndices, rightIndices };
    }

    // 5. Inner, Left, Right, and Outer index alignment
    const trackRight = how === "outer" || how === "right";
    const matchedRightIndices = trackRight ? new Uint8Array(rightHeight) : null;
    const keepUnmatchedLeft = how === "left" || how === "outer";

    for (let i = 0; i < leftHeight; i++) {
        const hash = getRowHashAt(leftCols, leftKeys, numLeftKeys, i);
        const matches = hash === null ? undefined : rightHash.get(hash);

        if (matches === undefined) {
            if (keepUnmatchedLeft) {
                leftIndices.push(i);
                rightIndices.push(null);
            }
            continue;
        }

        const matchCount = matches.length;
        for (let m = 0; m < matchCount; m++) {
            const rIdx = matches[m];
            if (trackRight) matchedRightIndices![rIdx] = 1;
            leftIndices.push(i);
            rightIndices.push(rIdx);
        }
    }

    // 6. Append unmatched right rows for Right & Outer joins
    if (trackRight) {
        _appendUnmatchedRightRows(leftIndices, rightIndices, matchedRightIndices!, rightHeight);
    }

    // 7. Order preservation: "left" and "none" naturally maintain left-table order
    const orderStrategy = maintainOrder || "none";
    if (orderStrategy === "none" || orderStrategy === "left") {
        return { leftIndices, rightIndices };
    }

    const len = leftIndices.length;
    const perm = new Int32Array(len);
    for (let idx = 0; idx < len; idx++) perm[idx] = idx;

    const getL = (i: number) => leftIndices[i] === UNMATCHED_ROW_INDEX ? Number.MAX_SAFE_INTEGER : leftIndices[i];
    const getR = (i: number) => rightIndices[i] ?? Number.MAX_SAFE_INTEGER;

    perm.sort((a, b) => {
        const diffR = getR(a) - getR(b);
        const diffL = getL(a) - getL(b);
        if (orderStrategy === "right") return diffR || (a - b);
        if (orderStrategy === "left_right") return diffL || diffR || (a - b);
        return diffR || diffL || (a - b);
    });

    const sortedLeft = new Array(len);
    const sortedRight = new Array(len);
    for (let idx = 0; idx < len; idx++) {
        const p = perm[idx];
        sortedLeft[idx] = leftIndices[p];
        sortedRight[idx] = rightIndices[p];
    }
    return { leftIndices: sortedLeft, rightIndices: sortedRight };
}

alignWhereIndices.code:
export function alignWhereIndices(
    leftCols: ColumnDict,
    rightCols: ColumnDict,
    leftHeight: number,
    rightHeight: number,
    predicates: IExpr[],
    options: JoinWhereOptions = {}
): { leftIndices: number[]; rightIndices: (number | null)[] } {
    const how = options.how ?? "inner";

    const emptyFastPath = _alignEmptySideIndices(how, leftHeight, rightHeight);
    if (emptyFastPath) return emptyFastPath;

    const [leftSuffix = "", rightSuffix = "_right"] = options.suffixes ?? ["", "_right"];
    const leftIndices: number[] = [];
    const rightIndices: (number | null)[] = [];

    const numPreds = predicates.length;
    const trackRight = how === "right";
    const matchedRightIndices = trackRight ? new Uint8Array(rightHeight) : null;

    const evalCols: ColumnDict = {};
    const initTargetKeys = (sourceCols: ColumnDict, checkCols: ColumnDict, suffix: string): string[] => {
        const keys = Object.keys(sourceCols);
        const len = keys.length;
        const targetKeys: string[] = new Array(len);
        for (let k = 0; k < len; k++) {
            const key = keys[k];
            const targetKey = (key in checkCols && suffix !== "") ? `${key}${suffix}` : key;
            targetKeys[k] = targetKey;
            evalCols[targetKey] = new Array(1);
        }
        return targetKeys;
    };

    const leftTargetKeys = initTargetKeys(leftCols, rightCols, leftSuffix);
    const rightTargetKeys = initTargetKeys(rightCols, leftCols, rightSuffix);
    const leftKeys = Object.keys(leftCols);
    const rightKeys = Object.keys(rightCols);
    const leftKeysLen = leftKeys.length;
    const rightKeysLen = rightKeys.length;

    const bindSideBuffers = (sourceCols: ColumnDict, keys: string[], targetKeys: string[]) => {
        const len = keys.length;
        const targetBuffers = new Array(len);
        const sourceColList = new Array(len);
        for (let k = 0; k < len; k++) {
            targetBuffers[k] = evalCols[targetKeys[k]];
            sourceColList[k] = sourceCols[keys[k]];
        }
        return { targetBuffers, sourceCols: sourceColList };
    };

    const { targetBuffers: leftTargetBuffers, sourceCols: leftSourceCols } = bindSideBuffers(leftCols, leftKeys, leftTargetKeys);
    const { targetBuffers: rightTargetBuffers, sourceCols: rightSourceCols } = bindSideBuffers(rightCols, rightKeys, rightTargetKeys);

    for (let i = 0; i < leftHeight; i++) {
        let leftMatched = false;

        for (let k = 0; k < leftKeysLen; k++) {
            leftTargetBuffers[k][0] = leftSourceCols[k][i];
        }

        rightLoop: for (let j = 0; j < rightHeight; j++) {
            for (let k = 0; k < rightKeysLen; k++) {
                rightTargetBuffers[k][0] = rightSourceCols[k][j];
            }

            for (let p = 0; p < numPreds; p++) {
                const evalRes = predicates[p]._evaluate(evalCols, 1);
                if (evalRes[0] !== true) continue rightLoop;
            }

            leftMatched = true;
            leftIndices.push(i);
            rightIndices.push(j);
            if (trackRight) matchedRightIndices![j] = 1;
        }

        if (!leftMatched && how === "left") {
            leftIndices.push(i);
            rightIndices.push(null);
        }
    }

    if (trackRight) {
        _appendUnmatchedRightRows(leftIndices, rightIndices, matchedRightIndices!, rightHeight);
    }

    return { leftIndices, rightIndices };
}

