export function buildGroupMap(columns: ColumnDict, keys: string[], height: number): GroupMap {
    const groups = new Map<string, number[]>();
    for (let i = 0; i < height; i++) {
        const hash = computeRowHash(columns, keys, i);
        let group = groups.get(hash);
        if (group === undefined) {
            groups.set(hash, group = []);
        }
        group.push(i);
    }
    return groups;
}

changeCase.code:
export function changeCase(str: unknown, options: ChangeCaseOptions): string {
    const words = toWords(str);
    const len = words.length;
    if (len === 0) return "";

    const { format } = options ?? {};
    if (!format) return words.join(" ");

    const delimiter = format === "kebab" ? "-" : format === "snake" ? "_" : format === "title" ? " " : "";
    const isLower = format === "kebab" || format === "snake";
    const result = new Array(len);

    for (let i = 0; i < len; i++) {
        const w = words[i];
        if (isLower || (i === 0 && format === "camel")) {
            result[i] = w.toLowerCase();
        } else {
            const step = _getCodePointStep(w, 0);
            result[i] = w.slice(0, step).toUpperCase() + w.slice(step).toLowerCase();
        }
    }

    return result.join(delimiter);
}

