computeIsIn.code:
export function computeIsIn(vArray: ArrayLike<unknown>, columns: unknown, values: unknown): unknown[] {
    const height = vArray.length;
    const exprValues = isExpr(values);
    const resolved = exprValues ? evaluateExpression(values, columns as ColumnDict, height) : null;
    const staticSet = exprValues ? null : buildCanonicalSet(values);
    const result = new Array(height);

    for (let i = 0; i < height; i++) {
        const v = vArray[i];
        if (v == null) {
            result[i] = null;
            continue;
        }
        const set = staticSet ?? buildCanonicalSet(resolved![i]);
        result[i] = set.has(toCanonicalString(v));
    }
    return result;
}

computeKurtosis.code:
export function computeKurtosis(arr: ArrayLike<unknown>, options: KurtosisOptions = {}): number | null {
    const stats = getCentralMoments(arr);
    if (!stats || stats.m2Sum <= 0) return null;

    const { count, m2Sum, m4Sum } = stats;
    const m2 = m2Sum / count;
    const m4 = m4Sum / count;
    const a4 = m4 / (m2 * m2);
    const g2 = a4 - 3;

    const fisher = options?.fisher ?? true;
    const bias = options?.bias ?? true;

    if (bias) {
        const val = fisher ? g2 : a4;
        return isValidNumber(val) ? val : null;
    }

    if (count < 4) return null;

    const G2 = ((count - 1) / ((count - 2) * (count - 3))) * ((count + 1) * g2 + 6);
    const val = fisher ? G2 : G2 + 3;
    return isValidNumber(val) ? val : null;
}

