computeRank.code:
export function computeRank(
    arr: unknown[],
    value: unknown,
    options: { ignoreNulls?: boolean; dense?: boolean } = {}
): number | null {
    if (value == null) return null;

    const cacheKey = options.dense ? "_denseRankCache" : "_rankCache";
    let valueToRank = (arr as unknown as Record<string, Map<unknown, number> | undefined>)[cacheKey];

    if (!valueToRank) {
        let targetArr = arr;
        if (options.ignoreNulls) {
            targetArr = [];
            const len = arr.length;
            for (let i = 0; i < len; i++) {
                if (arr[i] != null) targetArr.push(arr[i]);
            }
        }
        if (options.dense) {
            targetArr = Array.from(new Set(targetArr));
        }

        const sorted = sortArray(targetArr);
        valueToRank = new Map();
        const len = sorted.length;
        for (let i = 0; i < len; i++) {
            const v = sorted[i];
            if (!valueToRank.has(v)) {
                valueToRank.set(v, i + 1);
            }
        }
        (arr as unknown as Record<string, Map<unknown, number>>)[cacheKey] = valueToRank;
    }

    return valueToRank.get(value) ?? null;
}

computeRowHash.code:
export function computeRowHash(columns: ColumnDict, keys: string[], rowIndex: number): string {
    const len = keys.length;
    if (len === 1) {
        return toCanonicalString(columns[keys[0]][rowIndex]);
    }
    const vals = new Array(len);
    for (let i = 0; i < len; i++) {
        vals[i] = toCanonicalString(columns[keys[i]][rowIndex]);
    }
    return vals.join(KEY_SEPARATOR);
}

computeSkewness.code:
export function computeSkewness(arr: ArrayLike<unknown>, options: SkewOptions = {}): number | null {
    const stats = getCentralMoments(arr);
    if (!stats || stats.m2Sum <= 0) return null;

    const { count, m2Sum, m3Sum } = stats;
    const m2 = m2Sum / count;
    const m3 = m3Sum / count;
    const g1 = m3 / Math.pow(m2, 1.5);

    const bias = options?.bias ?? true;
    if (bias) {
        return isValidNumber(g1) ? g1 : null;
    }

    if (count < 3) return null;

    const G1 = (Math.sqrt(count * (count - 1)) / (count - 2)) * g1;
    return isValidNumber(G1) ? G1 : null;
}

