computeWeightedAverage.code:
export function computeWeightedAverage(pairs: ColumnData<[unknown, unknown]>): number | null {
    const len = pairs.length;
    let sumProducts = 0;
    let sumWeights = 0;
    let count = 0;

    for (let i = 0; i < len; i++) {
        const pair = pairs[i];
        if (!pair) continue;

        const x = toValidNumber(pair[0]);
        const w = toValidNumber(pair[1]);
        if (x === null || w === null) continue;

        sumProducts += x * w;
        sumWeights += w;
        count++;
    }

    if (count === 0 || Math.abs(sumWeights) < 1e-12) return null;
    return sumProducts / sumWeights;
}

