export function createUTCDate(
    year: number,
    monthZeroIndexed = 0,
    day = 1,
    hour = 0,
    minute = 0,
    second = 0,
    ms = 0
): Date {
    const d = new Date(0);
    d.setUTCFullYear(year, monthZeroIndexed, day);
    d.setUTCHours(hour, minute, second, ms);
    return d;
}

