export function evalUnaryOp(v: unknown, fn: (a: unknown) => unknown): unknown {
    if (v == null) return null;
    const normV = typeof v === "object" && isValidDateObj(v) ? v.getTime() : v;
    return fn(normV);
}

evaluateArg.code:
export function evaluateArg(
    arg: unknown,
    columns: ColumnDict | null | undefined,
    height: number
): unknown {
    if (isExpr(arg)) {
        return evaluateExpression(arg, columns || {}, height);
    }
    if (typeof arg === "string" && columns != null && (arg in columns)) {
        return columns[arg];
    }
    return arg;
}

evaluateArgsMatrix.code:
export function evaluateArgsMatrix(
    args: unknown[],
    columns: ColumnDict | null | undefined,
    height: number
): { evaluatedArrays: unknown[]; isCol: boolean[] } {
    const len = args.length;
    const evaluatedArrays = new Array(len);
    const isCol = new Array(len);

    for (let j = 0; j < len; j++) {
        const raw = args[j];
        const evaluated = evaluateArg(raw, columns, height);
        evaluatedArrays[j] = evaluated;
        isCol[j] = isEvaluatedColumn(raw, evaluated, columns, height);
    }

    return { evaluatedArrays, isCol };
}

evaluateExpression.code:
export function evaluateExpression(expr: IExpr, columns: ColumnDict, height: number): ColumnData {
    return expr._isWindow
        ? resolveWindowExpr(expr, columns, height)
        : expr._evaluate(columns, height);
}

extractRegex.code:
export function extractRegex(
    str: string | null | undefined,
    pattern: string | RegExp,
    options?: ExtractRegexEngineOptions
): string | null {
    const res = extractRegexEngine(str, pattern, options);
    return res ? _resolveGroupRecord(res[0], options?.groupIndex ?? 1) : null;
}

