    );

    // --- 11. Multi-line Strings with Global Patterns ---
    const multiLine = "row 100\nrow 200\nrow 300";
    assertEqual(
        extractRegexAll(multiLine, /^row\s+(\d+)$/m, { groupIndex: 1 }),
