    const emojiStr = "⭐️ 5 star, ⭐️ 4 star, ⭐️ 3 star";
    assertEqual(
        extractRegexAll(emojiStr, /⭐️\s+(\d+)/, { groupIndex: 1 }),
        ["5", "4", "3"],
        "extracts numbers following unicode emoji"
    );

