getArrayStats.code:
export function getArrayStats(arr: unknown): {
    sum: number | null;
    product: number | null;
    count: number;
    min: unknown;
    max: unknown;
    nanMin: unknown;
    nanMax: unknown;
    minIdx: number | null;
    maxIdx: number | null;
    mean: number | null;
    variance: number;
    std: number;
    nullCount: number;
    nanCount: number;
    len: number;
    hasNulls: boolean;
    isNumeric: boolean;
} {
    if (!isArrayOrTypedArray(arr)) {
        return DEFAULT_STATS;
    }
    const len = (arr as ArrayLike<unknown>).length;
    if (len === 0) {
        return DEFAULT_STATS;
    }

    let minVal: unknown = null;
    let maxVal: unknown = null;
    let minIdx: number | null = null;
    let maxIdx: number | null = null;
    let count = 0;
    let nullCount = 0;
    let nanCount = 0;
    let total = 0;
    let sumCompensation = 0;
    let product = 1;
    let mean = 0;
    let M2 = 0;

    for (let i = 0; i < len; i++) {
        const val = (arr as ArrayLike<unknown>)[i];
        if (val == null) {
            nullCount++;
            continue;
        }
        if (typeof val === "number" && Number.isNaN(val)) {
            nanCount++;
            nullCount++;
            continue;
        }

        if (minVal == null || val < minVal) {
            minVal = val;
            minIdx = i;
        }
        if (maxVal == null || val > maxVal) {
            maxVal = val;
            maxIdx = i;
        }

        const n = toValidNumber(val);
        if (n !== null) {
            // Neumaier sum
            const t = total + n;
            if (Math.abs(total) >= Math.abs(n)) {
                sumCompensation += (total - t) + n;
            } else {
                sumCompensation += (n - t) + total;
            }
            total = t;
            product *= n;

            count++;
            const delta = n - mean;
            mean += delta / count;
            const delta2 = n - mean;
            M2 += delta * delta2;
        }
    }

    const variance = count > 1 ? M2 / (count - 1) : 0;
    const hasNaN = nanCount > 0;

    return {
        sum: count > 0 ? total + sumCompensation : null,
        product: count > 0 ? product : null,
        count,
        min: minVal,
        max: maxVal,
        nanMin: hasNaN ? NaN : minVal,
        nanMax: hasNaN ? NaN : maxVal,
        minIdx,
        maxIdx,
        mean: count > 0 ? (total + sumCompensation) / count : null,
        variance,
        std: Math.sqrt(variance),
        nullCount,
        nanCount,
        len,
        hasNulls: nullCount > 0,
        isNumeric: count > 0 && count === (len - nullCount)
    };
}

