export function kleeneUnary(fn: (v: unknown) => unknown) {
    return (vArray: ColumnData) => {
        const height = vArray.length;
        const result = new Array(height);
        for (let i = 0; i < height; i++) {
            result[i] = evalUnaryOp(vArray[i], fn);
        }
        return result;
    };
}

