declare const process: any;
import { replaceString } from "../../../src/utils/string";

console.log("=========================================");
console.log("STARTING REPLACESTRING TESTS...");
console.log("=========================================");

let testsPassed = 0;

function assert(condition: boolean, msg: string) {
    if (!condition) throw new Error(`Assertion failed: ${msg}`);
    testsPassed++;
}

function assertEqual(actual: any, expected: any, msg: string) {
    const a = JSON.stringify(actual);
    const e = JSON.stringify(expected);
    if (a !== e) {
        throw new Error(`Assertion failed: ${msg}\n  Expected: ${e}\n  Actual:   ${a}`);
    }
    testsPassed++;
}

try {

    // 1. Basic & Null / Undefined Guards
    assertEqual(replaceString(null, "foo", "bar"), null, "null string returns null");
    assertEqual(replaceString(undefined, "foo", "bar"), null, "undefined string returns null");
    assertEqual(replaceString("hello", null as any, "bar"), null, "null pattern returns null");
    assertEqual(replaceString("hello", "foo", null as any), null, "null replacement returns null");
    assertEqual(replaceString("", "foo", "bar"), "", "empty string returns empty string");
    assertEqual(replaceString("hello", "", "X"), "Xhello", "empty string pattern matches at index 0");

    // 2. n options (counts, 0, negative, Infinity, floats)
    assertEqual(replaceString("aaaa", "a", "b", { n: 0 }), "aaaa", "n=0 performs no replacements");
    assertEqual(replaceString("aaaa", "a", "b", { n: 1 }), "baaa", "default n=1 replaces first occurrence");
    assertEqual(replaceString("aaaa", "a", "b", { n: 2 }), "bbaa", "n=2 replaces first 2 occurrences");
    assertEqual(replaceString("aaaa", "a", "b", { n: 2.9 }), "bbaa", "n=2.9 truncates to 2");
    assertEqual(replaceString("aaaa", "a", "b", { n: -1 }), "bbbb", "n=-1 replaces all occurrences");
    assertEqual(replaceString("aaaa", "a", "b", { n: Infinity }), "bbbb", "n=Infinity replaces all");
    assertEqual(replaceString("aaaa", "a", "b", { n: NaN }), "baaa", "n=NaN defaults to 1");

    // 3. Literal vs Regex Pattern with Special Regex Metacharacters
    const metaStr = "foo.[bar]*+?^${}()|baz";
    assertEqual(replaceString(metaStr, ".[bar]*+?^${}()|", "___", { literal: true }), "foo___baz", "literal: true ignores regex metachars");
    assertEqual(replaceString(metaStr, /\[bar\]/, "[qux]"), "foo.[qux]*+?^${}()|baz", "regex pattern matching brackets");

    // 4. Case sensitivity & asciiCaseInsensitive
    assertEqual(replaceString("Hello WORLD", "world", "earth", { asciiCaseInsensitive: true }), "Hello earth", "asciiCaseInsensitive single");
    assertEqual(replaceString("foo FOO Foo", "foo", "bar", { asciiCaseInsensitive: true, n: -1 }), "bar bar bar", "asciiCaseInsensitive global");
    assertEqual(replaceString("Hello World", /world/i, "Universe"), "Hello Universe", "RegExp /i flag");

    // 5. Replacement template tokens ($$, $&, $', $`, $1..$n, $<name>)
    const target = "item: apple price: 100";
    assertEqual(
        replaceString(target, /(apple)\s+price:\s+(\d+)/, "cost: $$ $2 for $1"),
        "item: cost: $ 100 for apple",
        "tokens $$ and positional capture groups $1, $2"
    );
    assertEqual(
        replaceString("foo-BAR-baz", "BAR", "[$&]", { literal: false }),
        "foo-[BAR]-baz",
        "token $& expands to full match"
    );
    assertEqual(
        replaceString("abcDEFghi", "DEF", "<$`>", { literal: false }),
        "abc<abc>ghi",
        "token $` expands to preceding substring"
    );
    assertEqual(
        replaceString("abcDEFghi", "DEF", "<$'>", { literal: false }),
        "abc<ghi>ghi",
        "token $' expands to succeeding substring"
    );
    assertEqual(
        replaceString("2026-09-12", /(?<year>\d{4})-(?<month>\d{2})-(?<day>\d{2})/, "$<month>/$<day>/$<year>"),
        "09/12/2026",
        "named capture groups $<name>"
    );

    // 6. Literal mode with replacement containing $ signs (must NOT expand)
    assertEqual(
        replaceString("Price is 100", "100", "$50 $& $1", { literal: true }),
        "Price is $50 $& $1",
        "literal: true does not expand $ tokens in replacement string"
    );

    // 7. Function replacement callbacks
    let callCount = 0;
    const fnResult = replaceString("apple 1, apple 2, apple 3", /apple\s+(\d+)/, (match, p1) => {
        callCount++;
        return `fruit #${p1}`;
    }, { n: 2 });
    assertEqual(fnResult, "fruit #1, fruit #2, apple 3", "callback replacement respecting n limit");
    assertEqual(callCount, 2, "callback called exact number of times requested by n");

    // 8. Empty & zero-length regex matches
    assertEqual(replaceString("abc", /(?=b)/, "-"), "a-bc", "zero-width lookahead assertion replacement");
    assertEqual(replaceString("abc", /^/, "[START]-"), "[START]-abc", "zero-width start of string anchor");
    assertEqual(replaceString("abc", /$/, "-[END]"), "abc-[END]", "zero-width end of string anchor");

    // 9. Unicode and multi-byte surrogate pairs
    const emoStr = "Hello 🌍 World 🚀";
    assertEqual(replaceString(emoStr, "🌍", "🪐", { literal: true }), "Hello 🪐 World 🚀", "surrogate pair literal replacement");
    assertEqual(replaceString(emoStr, /🚀/, "🛸"), "Hello 🌍 World 🛸", "surrogate pair regex replacement");

    // 10. Boundary: Pattern not found
    assertEqual(replaceString("The brown fox", "elephant", "cat"), "The brown fox", "unmatched pattern leaves input unchanged");
    assertEqual(replaceString("The brown fox", /zebra/g, "cat"), "The brown fox", "unmatched regex leaves input unchanged");


    console.log(`SUCCESS: All replaceString tests passed! (${testsPassed} assertions)`);
} catch (err) {
    console.error(`FAILURE: replaceString test failed!`, err);
    process.exit(1);
}

resolveColumnSelectors.code:
export function resolveColumnSelectors(
    exprs: unknown[],
    allKeys: string[],
    keysToExcludeFromAll?: string[],
    schema?: DataFrameSchema,
    columns?: ColumnDict
): IExpr[] {
    const expanded: IExpr[] = [];
    const excludeSet = keysToExcludeFromAll ? new Set(keysToExcludeFromAll) : new Set<string>();
    const len = exprs.length;

    for (let i = 0; i < len; i++) {
        const expr = exprs[i];

        if (typeof expr === "string") {
            expanded.push(new ColumnExpr(expr));
            continue;
        }

        // Handle struct unnesting expansion
        if (isObj(expr) && expr._isUnnest && expr._baseExpr) {
            const baseExpr = expr._baseExpr as IExpr;
            let fields: string[] = [];
            const colName = expr._colName;
            const baseHasOps = ((baseExpr as ColumnExprInternal)._ops?.length ?? 0) > 0;
            if (!baseHasOps && typeof colName === "string" && schema && schema[colName] && schema[colName].name === "Struct") {
                fields = Object.keys((schema[colName] as unknown as { fields: Record<string, unknown> }).fields);
            }
            if (fields.length === 0 && columns) {
                const columnsKeys = Object.keys(columns);
                const firstKey = columnsKeys[0];
                const height = firstKey ? columns[firstKey].length : 0;
                const evaluated = baseExpr._evaluate(columns, height);
                const evalLen = evaluated.length;
                for (let idx = 0; idx < evalLen; idx++) {
                    const item = evaluated[idx];
                    if (item != null && typeof item === "object") {
                        fields = Object.keys(item);
                        break;
                    }
                }
            }
            const fieldsLen = fields.length;
            if (fieldsLen > 0) {
                for (let fIdx = 0; fIdx < fieldsLen; fIdx++) {
                    const fieldName = fields[fIdx];
                    const fieldExpr = (baseExpr as ColumnExpr<unknown>).struct.field(fieldName);
                    expanded.push(fieldExpr);
                }
                continue;
            }
        }

        const typedExpr = expr as ColumnExpr<unknown>;
        const targets = _getTargetKeys(typedExpr, allKeys, excludeSet, schema);
        if (targets !== null) {
            const tLen = targets.length;
            for (let j = 0; j < tLen; j++) {
                const concrete = new ColumnExpr(targets[j]);
                concrete._ops = typedExpr._ops ? [...typedExpr._ops] : [];
                concrete._aggFn = typedExpr._aggFn;
                concrete._partitionOpsIndex = typedExpr._partitionOpsIndex;
                concrete._groupingOpsIndex = typedExpr._groupingOpsIndex;
                concrete._partitionBy = typedExpr._partitionBy;
                if (typedExpr._castType) concrete._castType = typedExpr._castType;
                if (typedExpr._evaluateWindow) concrete._evaluateWindow = typedExpr._evaluateWindow;
                if (typedExpr._outputName && typedExpr._outputName !== ALL_COLUMNS_MARKER) {
                    concrete._outputName = typedExpr._outputName;
                }
                expanded.push(concrete);
            }
        } else {
            expanded.push(typedExpr);
        }
    }

    return expanded;
}

resolveExprOutputType.code:
export function resolveExprOutputType(
    expr: IExpr,
    schema: DataFrameSchema,
    colSample?: ColumnData | unknown[]
): RegisteredDataType | undefined {
    if (!expr) return undefined;

    // 1. Direct explicit overrides
    if (expr._castType) return expr._castType;
    if ((expr as ColumnExprInternal)._targetType instanceof DataType) return (expr as unknown as { _targetType: RegisteredDataType })._targetType;

    const colName = expr._colName;
    const baseType = colName ? schema[colName] : undefined;
    const isBareCol = (!expr._ops || expr._ops.length === 0) && !expr._aggFn && !expr._evaluateWindow;

    if (baseType && isBareCol && !expr._isUnnest) return baseType;

    // 3. Literals
    if (expr._isLiteral && expr._literalValue !== undefined) {
        return _resolveOperandType(expr._literalValue, schema);
    }

    // 4. Expression AST branches (binary, coalesce/when-then, struct field)
    if (expr._binaryMeta) {
        return _deduceBinaryType(
            _resolveOperandType(expr._binaryMeta._left, schema),
            _resolveOperandType(expr._binaryMeta._right, schema),
            colSample
        );
    }
    if (expr._branchOperands) {
        let inferred: RegisteredDataType | undefined;
        for (let i = 0, len = expr._branchOperands.length; i < len; i++) {
            const t = _resolveOperandType(expr._branchOperands[i], schema);
            if (!t) continue;
            if (!inferred) {
                inferred = t;
                continue;
            }
            if (inferred !== t && inferred.isNumeric && t.isNumeric) {
                inferred = _deduceBinaryType(inferred, t, colSample) ?? inferred;
            }
        }
        if (inferred) return inferred;
    }
    if (expr._baseExpr && expr._fieldName) {
        const parent = _resolveOperandType(expr._baseExpr, schema);
        if (parent instanceof StructType) return parent.fields?.[expr._fieldName];
    }

    // 5. Schema column references & transformations (sampling only when needed)
    const sampleVal = colSample?.[0];

    if (baseType) {
        if (baseType instanceof ArrayType && (expr._isUnnest || (colSample as { rowMap?: unknown })?.rowMap)) return baseType.innerType;
        if (!(baseType instanceof ArrayType) && Array.isArray(sampleVal)) return DataTypeRegistry.Array(baseType);
        if (expr._aggFn) {
            if (baseType.isTemporal && (isValidDateObj(sampleVal) || typeof sampleVal === "string")) return baseType;
            if (baseType instanceof DurationType && isValidNumber(sampleVal)) return baseType;
        }
    }

    // 6. Statistical aggregations
    if (expr._aggFn && isValidNumber(sampleVal)) {
        if (!Number.isInteger(sampleVal) || (baseType?.isNumeric && !(baseType instanceof DurationType))) {
            return DataTypeRegistry.Float64;
        }
        return DataTypeRegistry.Int32;
    }

    return undefined;
}

