        throw new Error(`Expected i_dur_mul to be DurationType, got ${(durNumDf.schema["i_dur_mul"] as any)?.name}`);
    }

    // 69. 16-bit Integer Arithmetic Promotions
    const int16Df = $df.dataFrame({
