export function scaleDurationMs(ms: number, timeUnit: "ms" | "us" | "ns" | string): number {
    if (!isValidNumber(ms)) return NaN;
    const u = (timeUnit ?? "").toLowerCase();
    if (u === "us" || u === "µs" || u === "μs") return (ms * US_PER_MS) || 0;
    if (u === "ns") return (ms * NS_PER_MS) || 0;
    if (u === "ms") return ms || 0;
    return NaN;
}

