toEpoch.code:
export function toEpoch(d: Date, unit: TimeUnit = "ms"): number | bigint {
    const ms = d.getTime();
    switch (unit) {
        case "s": return Math.floor(ms / MS_PER_SECOND);
        case "ms": return ms;
        case "us": return BigInt(ms) * US_PER_MS_BI;
        case "ns": return BigInt(ms) * NS_PER_MS_BI;
    }
}

