export function unboxPrimitiveObj(v: unknown): unknown {
    if (!isObj(v)) return v;

    const len = _PRIMITIVE_VALUE_OFS.length;
    for (let i = 0; i < len; i++) {
        const fn = _PRIMITIVE_VALUE_OFS[i];
        if (fn) {
            try { return fn.call(v); } catch { }
        }
    }

    return v;
}

